<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#6d4aff"><title>KOVA AI STUDIO</title><link rel="manifest" href="/studio/manifest.webmanifest"><link rel="stylesheet" href="/studio/studio.css"></head><body><main><header><div><small>KOVA</small><h1>AI STUDIO</h1></div><span id="status">● vérification…</span></header><section class="hero"><p class="eyebrow">STUDIO ÉDITORIAL</p><h2>Transformez une idée en publication.</h2><textarea id="idea" placeholder="Exemple : créer une blague sur les développeurs"></textarea><div class="grid"><label>Ton<select id="tone"><option>conversationnel</option><option>drôle</option><option>professionnel</option><option>éducatif</option></select></label><label>Langue<select id="lang"><option>français</option><option>anglais</option></select></label></div><div class="actions"><button id="generate">Générer le texte</button><button id="handshake" class="soft">Vérifier KOVA</button></div></section><section class="card" id="result" hidden><h3>Aperçu éditable</h3><textarea id="content"></textarea><div class="grid"><label>Programmer<input id="when" type="datetime-local"></label><label>Visibilité<select id="visibility"><option value="public">Public</option><option value="followers">Abonnés</option><option value="private">Privé</option></select></label></div><div class="actions"><button id="publish">Publier maintenant</button><button id="schedule" class="soft">Planifier</button></div><p id="message"></p></section><section class="card"><h3>Historique</h3><div id="history">Chargement…</div></section></main><script src="/studio/studio.js"></script></body></html>